internal static class Program
{
    private static readonly List<(string Name,Func<Task> Work)> cases=[];
    private static string root="";
    [STAThread]
    public static int Main(string[] args)
    {
        root=Path.GetFullPath(Path.Combine("artifacts","tests",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")[..6]));Directory.CreateDirectory(root);
        var dispatcher=Dispatcher.CurrentDispatcher;SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(dispatcher));var exit=1;
        dispatcher.BeginInvoke(async()=>{try{exit=args.Contains("--editor-native")?await RunEditorOnly():args.Contains("--live-read-only")?await LiveProbe():await Run();}catch(Exception e){Console.Error.WriteLine(e);exit=1;}finally{dispatcher.BeginInvokeShutdown(DispatcherPriority.Background);}});Dispatcher.Run();return exit;
    }
    private static void Test(string name,Action work)=>cases.Add((name,()=>{work();return Task.CompletedTask;}));
    private static void TestAsync(string name,Func<Task> work)=>cases.Add((name,work));
    private static void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}; got {actual}.");}
    private static void True(bool value,string message="Assertion failed"){if(!value)throw new Exception(message);}
    private static async Task Throws<T>(Func<Task> action)where T:Exception { try{await action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name); }
    private static void Throws<T>(Action action)where T:Exception { try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name); }
    private static async Task<int> Run()
    {
        Test("INI byte-for-byte round trip with CRLF, comments, custom sections and disabled settings",()=>{const string text="; Intro\r\n[ Unknown ]\r\n;Foo=disabled\r\n  Key = value  ; retain me\r\n+Array=(A=1,B=2)\r\n\r\nTail=last";Equal(text,new IniDocument(text).ToString());});
        Test("INI visual edit retains surrounding whitespace and inline comment",()=>{var doc=new IniDocument("[S]\r\n  Key = 1.0  ; hello\r\nUnknown=42\r\n");doc.Set("S","Key","2.0");Equal("[S]\r\n  Key = 2.0  ; hello\r\nUnknown=42\r\n",doc.ToString());});
        Test("INI quoted comment characters remain values",()=>{var doc=new IniDocument("[S]\nName=\"A ; # B\" ; note\n");Equal("\"A ; # B\"",doc.Get("S","Name"));doc.Set("S","Name","\"C\"");True(doc.ToString().Contains("Name=\"C\" ; note"));});
        Test("INI add section and no-terminal-newline key",()=>{var doc=new IniDocument("[S]\nX=1");doc.Set("S","Y","2");Equal("2",doc.Get("S","Y"));doc.Set("New","Z","3");Equal("3",doc.Get("New","Z"));});
        Test("INI rejects duplicate visual scalar targets and newline injection",()=>{var doc=new IniDocument("[S]\nX=1\nX=2\n");Throws<InvalidOperationException>(()=>doc.Set("S","X","3"));Throws<ArgumentException>(()=>doc.Set("S","Y","x\nInjected=1"));});
