    private static async Task<int> RunEditorOnly(){ConfigurationIntegrityRegression.Register(TestAsync);NativeConfigurationRegression.Register(TestAsync,root);return await RunCases();}
    private static async Task<int> RunCases()
    {
        var results=new List<object>();var failures=0;
        foreach(var (name,work) in cases){var sw=Stopwatch.StartNew();try{await work();Console.WriteLine("PASS "+name);results.Add(new{name,passed=true,milliseconds=sw.ElapsedMilliseconds});}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+"\n"+e);results.Add(new{name,passed=false,error=e.ToString()});}}
        File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{total=cases.Count,passed=cases.Count-failures,failures,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{cases.Count-failures}/{cases.Count} passed. Evidence: {root}");return failures==0?0:1;
    }
