    private static async Task<int> LiveProbe()
    {
        // This explicit mode has no calls to Execute/Save/ChangeMap/Trust/LaunchEditor.
        var gateway=new LiveServerGateway(new ProcessRunner(),new Preferences(),root);var s=await gateway.RefreshAsync(default);
        var report=new Dictionary<string,object?>{{"timestamp",DateTimeOffset.Now},{"snapshot",s},{"productionMutations",0}};
        try{var files=await gateway.LoadConfigurationAsync(default);report["configuration"]=files.Select(f=>new{f.Name,f.RemotePath,f.Hash,Bytes=f.Bytes.Length,Keys=new IniDocument(f.Text).Entries().Count});}catch(Exception e){report["configurationError"]=Redactor.Clean(e.Message);}
        try{report["backups"]=await gateway.ListBackupsAsync(default);}catch(Exception e){report["backupError"]=Redactor.Clean(e.Message);}
        try{report["updateInformation"]=await gateway.CheckUpdatesAsync(default);}catch(Exception e){report["updateError"]=Redactor.Clean(e.Message);}
        foreach(var source in new[]{"Operators","Battlegroup"})try{var text=await gateway.ReadLogsAsync(source,null,default);report[source+"LogRead"]=new{Characters=text.Length,HasErrors=text.Contains("error",StringComparison.OrdinalIgnoreCase)};}catch(Exception e){report[source+"LogReadError"]=Redactor.Clean(e.Message);}
        foreach(var director in new[]{true,false})try{report[director?"directorAvailability":"fileBrowserAvailability"]=(await gateway.GetToolUriAsync(director,default)).AbsoluteUri;}catch(Exception e){report[director?"directorError":"fileBrowserError"]=Redactor.Clean(e.Message);}
        var path=Path.Combine(root,"live-read-only.json");File.WriteAllText(path,Redactor.Clean(JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true})));Console.WriteLine($"SSH: {s.SshConnected}; group: {s.Battlegroup}; maps: {s.Maps.Count}; issues: {s.Issues.Count}. Report: {path}");return s.SshConnected&&s.Maps.Count>0?0:1;
    }
